insert into public.app_settings (key, value) values
  ('catalog_version', '{"version":"2026-08-v6","created":"2026-08-07","description":"Motor kataloğuna INNOMATICS eklendi ve mil çapı (shaft_mm) alanı seed''e girdi; kaplin kataloğu 47 seri dosyasına bölünüp seri satır bazında okunur oldu; tampon kataloğu (kind=\"buffer\") ilk kez seed edildi; SKF SNL/SE tambur rulman yatakları bearing_housing türüyle eklendi","sources":{"couplings":"ÖZGÜN 28 tip / 387 satır (ozgun katalog 2019 1-b.pdf) · SIBRE 11 seri / 94 satır (02_SIBRE_Coupling-catalogue.pdf) · JAURE MT alt serileri MT/MTS/MTG/MTG-HD/MTF/MTFE/MTES + TCBR / 107 satır (JAURE MT Series_Gear Coupling.pdf, TCBR_Barrel Coupling.pdf) — toplam 47 dosya / 588 satır, 2026-08-06","wheels":"FEM 1.001 standart boyutları","ropes":"TS EN 12385 tabloları","motors":"GAMAK (148 motor, GAMAK Teknik Katalog 2022) + ABB (115 motor, M3BP 9AKK105944 EN 02-2020) + INNOMATICS (100 motor, SIMOTICS SD 1LE1503/1LE1603, Siemens D 81.1 12/2021) — hepsinde 2/4/6/8 kutup ve boyut tablosundan okunan mil çapı, toplam 363 satır, 2026-08-06","reducers":"YILMAZ D serisi (yürütme, 579) + M/N serisi (yürütme, 1292) + H/B serisi (kaldırma, 5407) — motorsuz güç devir tabloları, 2026-08-06 · SIMOGEAR paralel (yürütme, 488)","flender_reducers":"FLENDER MD 20.1 universal H1-H4 helisel ve B2-B4 konik-helisel: 146 tip/boyut, nominal T2N ve çevrim aralığı; her biri kaldırma ve yürütme kataloglarında sunulur — MD 20.1 2018, s.16-17, 2026-08-07","brakes":"SIBRE TE/USB/SHI + DERELİ DYF + GALVI NEWCOMEN N.HYD / NV.HYD (33 kasnak freni, DIN 15435, tüm geometri mm) — Galvi Kasnak Fren.pdf, 2026-08-07","bearings":"SKF Rolling Bearings PUB BU/P1 17000 EN (Haziran 2018): 60xx / 62xx / 63xx sabit bilyalı, 222xx / 223xx küresel makaralı, 512xx eksenel bilyalı, NU / NJ silindirik makaralı — 320 satır, tüm sınır ölçüleri mm, 2026-08-07","bearing_housings":"SKF Bearing Housings and Roller Bearing Units PUB BU/P1 13186/1 EN (Şubat 2015), bölüm 2.3: 222xx / 223xx küresel makaralı rulmanlar için SNL/SE silindirik yataklama eşleşmeleri — 28 satır, tüm ölçüler mm, 2026-08-07","buffers":"SIBRE SP hidrolik (33 ürün + 216 hücrelik kuvvet matrisi + 169 kısma iğnesi) — SIBRE Produktkatalog2022_Puffer_SP.pdf s.18-22 · Conductix-Wampfler kauçuk Program 0170 (67) + hücresel Program 0180 (55) — KAT0170-0002-EN · kauçuk yük diyagramları 10 çap (enerji-strok + kuvvet-strok eğrileri) — KAT0170-0003-EN · firma Excel''inden 11 teyit EDİLMEMİŞ ''Type NN HD'' satırı ayrı dosyada, 2026-08-06 — toplam 166 satır"},"notes":"Redüktörlerde application alanı kullanım grubunu taşır (kaldirma | yurutme); katalog seçicisinde bölüme göre kilitlidir. İzin verilen radyal yükler kN olarak saklanır. MOTOR: shaft_diameter_mm seed''de shaft_mm olarak yazılır ve 2.4/5.4 bölümlerinde motorShaftMm alanını doldurur; seri satırın kendi series alanından okunur, devir katalogun GERÇEK yüklü devridir (senkron devire yuvarlanmaz). KAPLİN: seri ve coupling_type satırın kendi alanlarından okunur — JAURE MT alt serileri ayrı ayrı seçilebilir; tambur kaplini bölümü drum + barrel kodlarına, motor kaplini bölümü gear/flexible/pin/disc/brake kodlarına kilitlidir. TAMPON: üç aile tek kind altındadır; enerji birimi ortak anahtarda kJ''dir (kauçuk katalog J basar, seed 1 J = 0,001 kJ ile çevirir, ham değer energy_j altında kalır). Kauçuk ve hücreselde strok katalogda basılı değildir, s = yükseklik · izin verilen sıkışma% / 100 ile türetilir. Kauçuk doğrusal değildir; ara nokta satıra iliştirilen energy_curve / force_curve dizilerinden okunur (yalnız conductix_curves.json''un applies_to_models listesindeki 13 ürün kodu; Ø40/Ø50/Ø63 eğrilerinin karşılığı olan silindirik ürün yoktur ve konik ürüne BAĞLANMAMIŞTIR). firma_excel_buffers.json satırları unverified: true taşır ve seçicide uyarı gösterilir."}'::jsonb)
on conflict (key) do update set value = excluded.value, updated_at = now();
